// @vitest-environment node
// Accuracy harness: our engine vs Skyfield/sgp4 reference values generated by
// validation/generate_reference.py. Writes docs/accuracy/phase2.md when
// WRITE_ACCURACY=1. Thresholds sit just above today's measured errors so a
// regression fails CI.
// Learn: docs/learn/09-accuracy.md
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { DEG, RAD } from '../math/constants.ts'
import { makeObserver, lookAtTeme } from '../frames/observer.ts'
import { satelliteJsPropagator } from '../propagate/satellitejs-adapter.ts'
import type { OmmElements, Satellite } from '../propagate/propagator.ts'
import { findAboveIntervals } from '../passes/finder.ts'
import { skyAt } from '../sky/sky.ts'
import { moonAt } from '../sky/tonight.ts'
import { moonPositionKm } from '../moon/moon.ts'
import { planetState, type PlanetId } from '../planets/planets.ts'
import { eveningFor } from '../sky/sunEvents.ts'
import { localDateKey } from '../time/zone.ts'
import type { Place } from '../place.ts'
import elements from '../__fixtures__/stations-2026-10-24.json'

type Obs = { latDeg: number; lonDeg: number; elevationM: number }
type Ref = {
  skyfield: string
  sgp4: string
  ephemeris: string
  eop: string
  satellites: Array<{
    noradId: number
    unixMs: number
    observer: Obs
    azDeg: number
    elDeg: number
    rangeKm: number
  }>
  sun: Array<{ unixMs: number; observer: Obs; azDeg: number; elDeg: number }>
  moon: Array<{
    unixMs: number
    observer: Obs
    azDeg: number
    elDeg: number
    rangeKm: number
    illumination: number
  }>
  planets: Array<{
    id: PlanetId
    unixMs: number
    observer: Obs
    azDeg: number
    elDeg: number
    magnitude: number
  }>
  riseSet: Array<{
    noradId: number
    observer: Obs
    fromMs: number
    toMs: number
    passes: Array<{ riseMs: number; setMs: number }>
  }>
  sunsets: Array<{ observer: Obs; fromMs: number; toMs: number; settingsMs: number[] }>
}

const REF_PATH = new URL('../../../validation/reference/reference.json', import.meta.url)
const hasRef = existsSync(REF_PATH)
const ref: Ref | null = hasRef ? (JSON.parse(readFileSync(REF_PATH, 'utf8')) as Ref) : null

const place = (o: Obs): Place => ({ id: 'ref', name: 'ref', ...o, timeZone: 'UTC' })

/** Great-circle separation between two (az, el) directions, degrees. */
function separationDeg(az1: number, el1: number, az2: number, el2: number): number {
  const a = Math.sin(el1 * DEG) * Math.sin(el2 * DEG)
  const b = Math.cos(el1 * DEG) * Math.cos(el2 * DEG) * Math.cos((az1 - az2) * DEG)
  return Math.acos(Math.min(1, a + b)) * RAD
}

function stats(xs: number[]) {
  const sorted = [...xs].sort((a, b) => a - b)
  const mean = xs.reduce((s, x) => s + x, 0) / Math.max(1, xs.length)
  const p95 = sorted[Math.floor(0.95 * (sorted.length - 1))] ?? 0
  return { n: xs.length, mean, p95, max: sorted.at(-1) ?? 0 }
}
type Stats = ReturnType<typeof stats>

const report: Record<string, Stats & { unit: string }> = {}

describe.runIf(hasRef)('accuracy vs Skyfield', () => {
  const r = ref as Ref
  const sats = new Map<number, Satellite>(
    (elements as OmmElements[]).map((e) => [e.NORAD_CAT_ID, satelliteJsPropagator.init(e)]),
  )
  const satFor = (id: number) => {
    const s = sats.get(id)
    if (!s) throw new Error(`no fixture for ${id}`)
    return s
  }

  it('satellite position through our time and frame pipeline', () => {
    const posErrM: number[] = []
    const angErr: number[] = []
    for (const c of r.satellites) {
      const sky = skyAt(c.unixMs)
      const look = lookAtTeme(
        makeObserver(place(c.observer)),
        satFor(c.noradId).propagate(c.unixMs).rTeme,
        sky.gmstRad,
      )
      const sep = separationDeg(look.azDeg, look.elDeg, c.azDeg, c.elDeg)
      const lateralKm = c.rangeKm * sep * DEG
      posErrM.push(Math.hypot(lateralKm, look.rangeKm - c.rangeKm) * 1000)
      if (c.elDeg > 0) angErr.push(sep * 3600)
    }
    report['Satellite position (all geometry)'] = { ...stats(posErrM), unit: 'm' }
    report['Satellite direction (when above horizon)'] = { ...stats(angErr), unit: '″' }
    expect(stats(posErrM).max).toBeLessThan(25)
  })

  it('rise / set times at 10°', () => {
    const errS: number[] = []
    for (const w of r.riseSet) {
      const ours = findAboveIntervals(satFor(w.noradId), place(w.observer), w.fromMs, w.toMs)
      for (const p of w.passes) {
        const m = ours.find((o) => Math.abs(o.rise - p.riseMs) < 120_000)
        expect(m, `missed pass rising ${new Date(p.riseMs).toISOString()}`).toBeDefined()
        if (m) errS.push(Math.abs(m.rise - p.riseMs) / 1000, Math.abs(m.set - p.setMs) / 1000)
      }
    }
    report['Rise/set time at 10°'] = { ...stats(errS), unit: 's' }
    expect(stats(errS).max).toBeLessThan(1)
  })

  it('Sun direction', () => {
    const err = r.sun.map((c) => {
      const sky = skyAt(c.unixMs)
      const l = lookAtTeme(makeObserver(place(c.observer)), sky.sunTeme, sky.gmstRad)
      return separationDeg(l.azDeg, l.elDeg, c.azDeg, c.elDeg) * 3600
    })
    report['Sun direction'] = { ...stats(err), unit: '″' }
    expect(stats(err).max).toBeLessThan(60)
  })

  it('sunset times', () => {
    const err: number[] = []
    for (const s of r.sunsets) {
      const p = place(s.observer)
      for (const ms of s.settingsMs) {
        // Our evenings run noon→noon local; with timeZone UTC, start the search
        // from the UTC date of (sunset − 12 h) so the sunset falls inside it.
        for (const key of [localDateKey(ms - 12 * 3_600_000, 'UTC'), localDateKey(ms, 'UTC')]) {
          const ev = eveningFor(p, key)
          if (ev.sunsetMs !== null && Math.abs(ev.sunsetMs - ms) < 3_600_000) {
            err.push(Math.abs(ev.sunsetMs - ms) / 1000)
            break
          }
        }
      }
    }
    report['Sunset time'] = { ...stats(err), unit: 's' }
    expect(err.length).toBeGreaterThan(200)
    expect(stats(err).max).toBeLessThan(30)
  })

  it('Moon direction and illumination', () => {
    const dir: number[] = []
    const illum: number[] = []
    for (const c of r.moon) {
      const sky = skyAt(c.unixMs)
      const l = lookAtTeme(makeObserver(place(c.observer)), moonPositionKm(sky.jdTt), sky.gmstRad)
      dir.push(separationDeg(l.azDeg, l.elDeg, c.azDeg, c.elDeg) * 60)
      illum.push(Math.abs(moonAt(place(c.observer), c.unixMs).illumination - c.illumination) * 100)
    }
    report['Moon direction (topocentric)'] = { ...stats(dir), unit: '′' }
    report['Moon illuminated fraction'] = { ...stats(illum), unit: '% pts' }
    expect(stats(dir).max).toBeLessThan(6)
    expect(stats(illum).max).toBeLessThan(1.5)
  })

  it('planet direction and magnitude', () => {
    const dir: number[] = []
    const mag: number[] = []
    for (const c of r.planets) {
      const sky = skyAt(c.unixMs)
      const st = planetState(c.id, sky.jdTt)
      const l = lookAtTeme(makeObserver(place(c.observer)), st.positionKm, sky.gmstRad)
      dir.push(separationDeg(l.azDeg, l.elDeg, c.azDeg, c.elDeg) * 60)
      // Magnitude only matters when the planet is a naked-eye object; Mercury
      // near inferior conjunction (thin crescent, lost in twilight) is where the
      // 1984 formulas and Skyfield's Mallama & Hilton (2018) models disagree most.
      if (c.magnitude <= 2) mag.push(Math.abs(st.magnitude - c.magnitude))
    }
    report['Planet direction'] = { ...stats(dir), unit: '′' }
    report['Planet magnitude (when brighter than mag 2)'] = { ...stats(mag), unit: 'mag' }
    expect(stats(dir).max).toBeLessThan(12)
    expect(stats(mag).max).toBeLessThan(0.4)
  })

  afterAll(() => {
    if (!process.env.WRITE_ACCURACY) return
    const fmt = (x: number) => (x >= 100 ? x.toFixed(0) : x >= 1 ? x.toFixed(2) : x.toPrecision(2))
    const rows = Object.entries(report).map(
      ([k, s]) => `| ${k} | ${s.n} | ${fmt(s.mean)} | ${fmt(s.p95)} | ${fmt(s.max)} | ${s.unit} |`,
    )
    const md = `# Accuracy report: Phase 2 engine vs Skyfield

_Generated by \`npm run accuracy\`. Do not edit by hand._

Reference: Skyfield ${r.skyfield}, sgp4 ${r.sgp4}, JPL ${r.ephemeris}, Earth orientation from ${r.eop}
(generator: \`validation/generate_reference.py\`, fixed seed, random observers within ±60° latitude).
Ours: satellite.js 7.1.0 propagator (TEMPORARY until Phase 4) plus our own time scales,
frames, Sun, Moon, planets and pass finder.

| Quantity | Cases | Mean | 95th pct | Max | Unit |
|---|---:|---:|---:|---:|---|
${rows.join('\n')}

How to read this: [docs/learn/09-accuracy.md](../learn/09-accuracy.md). Both sides run the
same SGP4 algorithm, so the satellite rows measure our *time and frame handling*, not how
well SGP4 predicts the real station days ahead. That second question needs field
observations (Phase 8).
`
    writeFileSync(new URL('../../../docs/accuracy/phase2.md', import.meta.url), md)
  })
})
